@pytest.mark.asyncio
async def test_index_task_completion_is_observable(service):
    task = asyncio.create_task(service.index('sku-1'))
    await task
    assert service.completed_items == {'sku-1'}

@pytest.mark.asyncio
async def test_index_task_cancellation_is_observable(service):
    task = asyncio.create_task(service.index('sku-1'))
    task.cancel()
    with pytest.raises(asyncio.CancelledError):
        await task
    assert service.cancelled_items == {'sku-1'}

