test('shows the selected product', async () => {
  const first = deferred();
  render(<Product id="a" load={() => first.promise} />);
  rerender(<Product id="b" load={() => Promise.resolve({ name: 'B' })} />);
  first.resolve({ name: 'A' });
  await screen.findByText('B');
});

test('keeps the current product after stale completion', async () => {
  const first = deferred();
  render(<Product id="a" load={() => first.promise} />);
  rerender(<Product id="b" load={() => Promise.resolve({ name: 'B' })} />);
  await screen.findByText('B');
  first.resolve({ name: 'A' });
  await waitFor(() => expect(screen.queryByText('A')).toBeNull());
  expect(screen.getByText('B')).toBeVisible();
});

